class Solution {
    public String maximumBinaryString(String binary) {
        int n = binary.length();
        int firstZero = binary.indexOf('0');
        if (firstZero == -1) return binary;
        int zeros = 0;
        for (int i = 0; i < n; ++i) if (binary.charAt(i) == '0') zeros++;
        int onesAfter = 0;
        for (int i = firstZero + 1; i < n; ++i) if (binary.charAt(i) == '1') onesAfter++;
        StringBuilder sb = new StringBuilder(n);
        // ones before first zero
        for (int i = 0; i < firstZero; ++i) sb.append('1');
        // ones created from zeros except the single remaining zero
        for (int i = 0; i < zeros - 1; ++i) sb.append('1');
        // the single zero
        sb.append('0');
        // append the ones that were to the right of the first zero
        for (int i = 0; i < onesAfter; ++i) sb.append('1');
        return sb.toString();
    }
}

